from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable tile size for the column dimension in the U-update.
# This improves cache locality and makes the inner j-loop more
# amenable to auto-vectorization by the C compiler.
TILE_J = 64


@proc
def kernel_lu(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Scratch array holding reciprocals of the pivots U[j, j]:
    #   invD[j] = 1 / U(j, j) once row j has been completed.
    # This replaces O(n^2) divisions in the L-update with
    # O(n^2) multiplications + O(n) divisions.
    invD: DATA_TYPE[n] @ DRAM

    # Outer pivot row loop. This must remain sequential because
    # each row i depends on all previous rows 0..i-1.
    for i in seq(0, n):

        # ----------------------------------------------------
        # 1) L-update: compute strictly lower entries A[i, j]
        #    for j in [0, i).
        #
        #    Mathematically:
        #      L(i, j) = ( A(i, j) - sum_{k=0}^{j-1} L(i, k) * U(k, j) )
        #                 / U(j, j)
        #
        #    Here we express this as a scalar accumulator 'tmp'
        #    and use the precomputed reciprocal invD[j]:
        #      L(i, j) = (A(i, j) - dot) * invD[j]
        #
        #    The j-loop is inherently sequential because A[i, j]
        #    depends on all A[i, k] with k < j.
        # ----------------------------------------------------
        for j in seq(0, i):
            # Accumulator for A[i, j] - sum_{k<j} A[i, k] * A[k, j]
            tmp: DATA_TYPE
            tmp = A[i, j]

            # Subtract the dot product over k = 0..j-1.
            for k in seq(0, j):
                tmp += -A[i, k] * A[k, j]

            # Divide by U(j, j) via multiplication by its reciprocal.
            # For i > j, invD[j] was computed at the end of row j.
            A[i, j] = tmp * invD[j]

        # ----------------------------------------------------
        # 2) U-update: compute diagonal and upper entries
        #    A[i, j] for j in [i, n).
        #
        #    Original Exo kernel:
        #      for j in seq(i, n):
        #          for k in seq(0, i):
        #              A[i, j] += -A[i, k] * A[k, j]
        #
        #    We rewrite this as:
        #      for k in seq(0, i):
        #          aik = A[i, k]
        #          for each column j >= i:
        #              A[i, j] += -aik * A[k, j]
        #
        #    and then tile j into chunks of size TILE_J:
        #      j = JJ * TILE_J + jj
        #
        #    Guards on j ensure j is in [i, n), and every (i, j)
        #    receives the same sum over k as in the original code,
        #    just in a different (but mathematically equivalent)
        #    accumulation order.
        # ----------------------------------------------------
        for k in seq(0, i):
            aik: DATA_TYPE
            aik = A[i, k]

            # Number of column tiles is ceil(n / TILE_J).
            for JJ in seq(0, (n + TILE_J - 1) / TILE_J):
                for jj in seq(0, TILE_J):
                    # Global column index within this tile.
                    j_col: size
                    j_col = JJ * TILE_J + jj

                    # Only update entries on or above the diagonal and
                    # within matrix bounds: i <= j_col < n.
                    if j_col >= i and j_col < n:
                        A[i, j_col] += -aik * A[k, j_col]

        # ----------------------------------------------------
        # 3) Store reciprocal of the pivot U(i, i) for use in
        #    future L-updates on rows r > i.
        #    After finishing row i, A[i, i] will not change again.
        # ----------------------------------------------------
        invD[i] = 1.0 / A[i, i]
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_lu (/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
