        #           A[i, j] += -A[i, k] * A[k, j]
        #       A[i, j] = A[i, j] / A[j, j]
        #
        # We rewrite this to use a scalar accumulator and D[j] = 1 / A[j, j]
        # (computed after finishing row j):
        #
        #   tmp = A[i, j] - sum_{k<j} A[i, k] * A[k, j]
        #   A[i, j] = tmp * D[j]
        #
        # This preserves the LU factorization while turning O(n^2)
        # divisions into O(n^2) multiplications + O(n) divisions.
        for j in seq(0, i):
            tmp: DATA_TYPE
            tmp = A[i, j]
            for k in seq(0, j):
                tmp += -A[i, k] * A[k, j]
            A[i, j] = tmp * D[j]

        # -------------------------------------------------------------
        # 2) Compute U's row i: diagonal and upper entries A[i, j] for j ≥ i
        # -------------------------------------------------------------
        #
        # Original kernel:
        #   for j in seq(i, n):
        #       for k in seq(0, i):
        #           A[i, j] += -A[i, k] * A[k, j]
        #
        # which is:
        #   A[i, j] = A[i, j] - sum_{k<i} A[i, k] * A[k, j]
        #
        # Here we:
        #   - Keep the mathematical formula identical.
        #   - Change the loop order to make k outermost, so that
        #     A[i, k] is reused from a scalar register across many j.
        #   - Tile the j-dimension into contiguous blocks of size TILE_J,
        #     improving cache locality for both A[i, j] and A[k, j].
        #
        # For each fixed (i, k), updates on different j are independent,
        # so reordering across j does not change the value of each A[i, j]
        # other than normal floating-point re-association effects.
        for k in seq(0, i):
            a_ik: DATA_TYPE
            a_ik = A[i, k]

            # Tile columns j in blocks of TILE_J.
            for JJ in seq(0, (n + TILE_J - 1) // TILE_J):
                for j in seq(0, TILE_J):
                    # Global column index for this tile element.
                    # Guard to ensure 0 ≤ j_global < n and j_global ≥ i.
                    if TILE_J * JJ + j >= i and TILE_J * JJ + j < n:
                        A[i, TILE_J * JJ + j] += -a_ik * A[k, TILE_J * JJ + j]

        # -------------------------------------------------------------
        # 3) Cache reciprocal of the diagonal pivot for future rows
        # -------------------------------------------------------------
        #
        # After step (2), A[i, i] holds U(i, i) and will not change again.
        # We store its reciprocal once, and all later L-updates that
        # need to divide by U(i, i) will instead multiply by D[i].
        D[i] = 1.0 / A[i, i]
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_lu (/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
