from exo import *
from exo.API_scheduling import *  # import scheduling API as required
from exo.libs.memories import DRAM

# Tile size for columns in the U-update. This improves cache locality and
# enables efficient SIMD on contiguous segments of A's rows.
TILE_J = 32


@proc
def kernel_lu(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Scratch buffer for reciprocals of U's diagonal entries.
    # D[j] = 1 / U(j, j) after row j is finalized.
    # Size is O(n), negligible compared to A's O(n^2) footprint.
    D: DATA_TYPE[n] @ DRAM

    # In-place LU factorization without pivoting.
    # On exit:
    #   - For i > j: A[i, j] holds L(i, j), with implicit unit diagonal L[i, i] = 1.
    #   - For i <= j: A[i, j] holds U(i, j).
    for i in seq(0, n):

        # ---------------------------------------------------------------
        # 1. Compute the L row: A[i, j] for j in [0, i)
        #
        #    L(i, j) = (A(i, j) - sum_{k<j} L(i, k) * U(k, j)) / U(j, j)
        #
        # We realize this with an explicit accumulator "tmp" to keep A[i, j]
        # in a register during the inner k-loop, reducing memory traffic.
        # The division by U(j, j) is implemented as a multiplication by its
        # precomputed reciprocal D[j].
        # ---------------------------------------------------------------
        for j in seq(0, i):
            # Accumulate A[i, j] - sum_{k<j} A[i, k] * A[k, j]
            tmp: DATA_TYPE
            tmp = A[i, j]
            for k in seq(0, j):
                tmp += -A[i, k] * A[k, j]

            # Divide by U(j, j) via multiplication with its reciprocal.
            # For all j < i, row j has already been fully processed and
            # D[j] has been set to 1.0 / A[j, j].
            A[i, j] = tmp * D[j]

        # ---------------------------------------------------------------
        # 2. Compute the U row: A[i, j] for j in [i, n)
        #
        #    U(i, j) = A(i, j) - sum_{k<i} L(i, k) * U(k, j)
        #
        # Original Exo kernel:
        #   for j in seq(i, n):
        #       for k in seq(0, i):
        #           A[i, j] += -A[i, k] * A[k, j]
        #
        # We reorder and tile the loops as:
        #   for k in seq(0, i):
        #       aik = A[i, k]
        #       for J in tiles of j:
        #           for jj in tile:
