        #               if i <= j < n:
        #                   A[i, j] += -aik * A[k, j]
        #
        # This:
        #   - Keeps A[i, k] in a scalar (aik) across many j updates.
        #   - Traverses A[k, j] and A[i, j] along rows (unit stride).
        #   - Tiles the j dimension for better cache behavior.
        #   - Preserves the per-(i, j) accumulation order over k.
        # ---------------------------------------------------------------
        for k in seq(0, i):
            aik: DATA_TYPE
            aik = A[i, k]

