        # can use multiplication by D[i] instead of division by A[i, i].
        # This replaces O(n^2) divisions with O(n^2) multiplications
        # plus O(n) divisions, which is typically much faster and
        # more SIMD-friendly while preserving the LU factorization.
        # ---------------------------------------------------------------
        D[i] = 1.0 / A[i, i]
